package com.example.rokidkeyboardbridge;
/** Machine-readable interpretation of the existing reviewed pose catalogue, not inferred anatomy. */
final class ConversationImageMetadata {
 static String scene(FullBodyPoseCatalog.Pose p){String g=p.gesture;if(p.supports(FullBodyPoseCatalog.Kind.WALK))return "WALKING";if(g.contains("protect")||p.supports(FullBodyPoseCatalog.Kind.REFUSE))return "BOUNDARY";if(g.contains("chin")||p.supports(FullBodyPoseCatalog.Kind.THINK))return "THINKING";if(p.supports(FullBodyPoseCatalog.Kind.CRY)||p.supports(FullBodyPoseCatalog.Kind.SAD)||p.supports(FullBodyPoseCatalog.Kind.WORRY))return "CONCERN";if(p.supports(FullBodyPoseCatalog.Kind.BREATH)||p.supports(FullBodyPoseCatalog.Kind.PANT)||p.supports(FullBodyPoseCatalog.Kind.STRAIN))return "EFFORT";if(g.contains("palm")||p.supports(FullBodyPoseCatalog.Kind.EXPLAIN))return "EXPLAINING";if(p.supports(FullBodyPoseCatalog.Kind.SURPRISE))return "SURPRISE";if(p.supports(FullBodyPoseCatalog.Kind.JOY)||p.supports(FullBodyPoseCatalog.Kind.SHY)||p.supports(FullBodyPoseCatalog.Kind.CONFIDENT))return "WARMTH";return "CALM";}
 static String posture(FullBodyPoseCatalog.Pose p){return p.seated?"SEATED":"STANDING";}
 static boolean spontaneous(FullBodyPoseCatalog.Pose p){return p.intensity<=1&&!p.supports(FullBodyPoseCatalog.Kind.WALK)&&!p.supports(FullBodyPoseCatalog.Kind.PANT)&&!p.supports(FullBodyPoseCatalog.Kind.BREATH)&&!p.supports(FullBodyPoseCatalog.Kind.STRAIN)&&!p.supports(FullBodyPoseCatalog.Kind.REFUSE)&&!p.supports(FullBodyPoseCatalog.Kind.ANGER)&&!p.supports(FullBodyPoseCatalog.Kind.CRY);}
 static String avoid(FullBodyPoseCatalog.Pose p){return "OTHER_POSTURE|NAVIGATION|RECORDING|"+(spontaneous(p)?"UNMATCHED_EMOTION":"UNRELATED_IDLE");}
 static int score(FullBodyPoseCatalog.Pose p,FullBodyPoseCatalog.Kind kind,int intensity,int current){boolean seated=current>=0&&FullBodyMotionPolicy.isSeated(current);return !p.supports(kind)||p.seated!=seated?-1:Math.abs(p.intensity-Math.max(0,Math.min(3,intensity)))*4;}
}
